%[text] %[text:anchor:T_360F0929] # EEG Artifacts
%[text] This script investigates how tACS stimulation artifacts affect EEG/LFP analysis and shows results for FASTR, FBAR, and RBAR algorithms.
%[text:tableOfContents]{"heading":"Table of Contents"}

%%
%[text] %[text:anchor:H_D32E8D0B] ## Setup Simulation
%[text] First define the stimulation and recording parameters.
startup; % Make sure all toolboxes are on the path

eegDefaults.reproducible              = true;    % Fix the random number generator to get reproducible results
%[text] Stimulation and Recording Equipment:
eegDefaults.stimulatorSamplingRate    = 1e3;     % 1 kHz 

eegDefaults.currentResolution         = 1e-6;    % 1 muA

eegDefaults.recordingSamplingRate     = 5e3;     % 5kHz
eegDefaults.adcLinearRange            = 200e-3;     % [V] Range over which the amplifier is linear
eegDefaults.adcNonlinearity           = 100;       % linear inside the range,saturation outside
eegDefaults.adcRange                  = 200e-3;     % The range of the ADC; bits are distributed evenly across this +/- range.
eegDefaults.adcBitDepth               = 24;       % Number of bits in the ADC
eegDefaults.adcGain                    = 1;        % Amplifier gain


eegDefaults.highPass                  = 0.01;    % Analog filter of the recording amplifier
eegDefaults.lowPass                   = 100;
%[text] Experiment:

eegDefaults.duration                  = 2*60;   % 2 min of data
eegDefaults.tacsFrequency             = 0;
eegDefaults.tacsAmplitude             = 0;
eegDefaults.tdcsMean                  = 0;
%[text] Signals. Setting everything except the background to 0.
eegDefaults.additive                  = 100e-6;   % Background Noise stdev
eegDefaults.lfpAmplitude              = 0;
eegDefaults.multiplicative            = 0;
eegDefaults.zAmplitude                = 0;

%[text] And setup the base parameters for artifiact removal
arDefaults.slide                     = false;   % No sliding segment
arDefaults.slack                     = 5e-3;    % 5 ms to realign segments
arDefaults.nrSegsPerWindow           = 10;      % 10 segments to average artifact
arDefaults.pcaNr                     = 2;       % First two PC are removed
arDefaults.pcaVarExplained           = Inf;     % Ignore explained variance, always remove 2.
arDefaults.pcaNrSegsPerWindow        = Inf;     % Use all segments (plus the tCS signal; below) to determine basis set.
arDefaults.referenceSegment          = 1;       % Align to first segment
arDefaults.recordingSamplingRate      = eegDefaults.recordingSamplingRate; % Match to the recording
arDefaults.segmentDuration          = 3;

%%
%[text] %[text:anchor:H_DDD99D7B] ## Recovering the neural background with FASTR
%[text] Create the artSim object using the default parameters defined above, then add tACS to the simulation 
eeg                   = artSim(eegDefaults);
eeg.tacsAmplitude     = 1e-3;    % 1 mA 
eeg.resistance        = 15;     % 1 mA - > 100 mV artifact
eeg.tacsFrequency     = 10;      % 10 Hz

%[text] First, investigate the FASTR algorithm (Niazy et al.). Match the artificat removal parameters to the data
ar                          = arDefaults;
ar.tacsFrequency            = eeg.tacsFrequency;

%[text] Generate figures
[~,axs] = fig('Name','Fig2','nrCols',1,'height',12,'nrRows',3,'byColumn',false); %[output:3e9fb433]
simPlotEEG(eeg,ar,'FASTR',axs=axs); %[output:771ddb35] %[output:7affaad8] %[output:035b4169] %[output:3e9fb433]
nexttile(1); legend off; %[output:3e9fb433]
nexttile(2); legend(["Neural", "Recovered", "Recorded"]) %[output:3e9fb433]
nexttile(3);yyaxis left;ylim([-10 10]); yyaxis right; ylim([-4 4]); %[output:3e9fb433]
%[text] Note that the Neural ground truth and the Recovered signals are generally small and show on the left y-axis. The recorded signal, which includes the artifact, is typically orders of magnitude larger - this graph shows it (blue) on the right y-axis. The figure shows that the recovered signal qualitatively matches the neural signal (green vs.red), but a  closer look , expressing errors as a percentage of the neural signal show substantial underestimation of the neural signal not only near the tACS frequency, but across the entire spectrum. 
%[text] The low-resolution spectral analysis hides some important detals. Rerun it now with 0.1 Hz frequency resolution:
[~,axs] = fig('Name','Fig3','paperCols',1,'height',9,'nrRows',2,'byColumn',false); %[output:1cf541e3]

simPlotEEG(eeg,ar,'FASTR',freqRes =0.1,axs=[gobjects(1) axs'],legend=false); %[output:64535db2] %[output:0d4a0c06] %[output:3929b784] %[output:1cf541e3]
%[text] This shows the clear comb artifact that repeats at `o.tacsFrequency/o.nrCycles`, here 10/30 = 0.33 Hz.
%%
%[text] %[text:anchor:H_1272639C] ## Recovering neural signals and background
%[text] Next, we *add* a neural signal in the form of an LFP/EEG signal that peaks at 32 hz, with some spectral spread around that:
eeg.lfpFrequency              = 32;        % Simulated oscillation peak frequency
eeg.lfpAmplitude              = 100e-6;    % Oscillation peak amplitude
eeg.lfpPeakWidth              = 1;         % Oscillation bandwidth.

%[text] Generate two figures, one for the time course, one for the error spectrum.
[~,axs4] = fig('Name','Fig4','paperCols',1,'height',10,'nrRows',3,'nrCols',1,'byColumn',false); %[output:9a30516c]
[~,axs5] = fig('Name','Fig5','paperCols',2,'height',5,'nrRows',1,'nrCols',3,'byColumn',false); %[output:1c9bc7fc]
%[text] %[text:anchor:H_218F3721] ### FASTR

rFastr= simPlotEEG(eeg,ar,'FASTR',freqRes =0.1,axs=[axs4(1) gobjects(1) axs5(1)]); %[output:2692722e] %[output:1786772a] %[output:71cbdf12] %[output:9a30516c] %[output:1c9bc7fc]
%[text] ### FBAR
%[text] We continue analyzing the same data, but now with a Fourier based algorithm (FBAR), using the same parameters

rFbar= simPlotEEG(eeg,ar,'FBAR',freqRes =0.1,axs=[axs4(2) gobjects(1)  axs5(2)]); %[output:0903f33f] %[output:9a30516c] %[output:1c9bc7fc]
%[text] %[text:anchor:H_AAE631F7] ### RBAR
%[text] And a regression based method:
rRbar = simPlotEEG(eeg,ar,'RBAR',freqRes =0.1,axs=[axs4(3)  gobjects(1) axs5(3)]); %[output:9a30516c] %[output:9c9e3bcc] %[output:1c9bc7fc]

yylinkaxes(axs5); % After plots have been generated - link to get the same scale %[output:1c9bc7fc]

%[text] 
%[text] This graph shows a 100 ms snippet of the data (red; with the 32 Hz oscillation) and recovered signal (green). Visually, FASTR does not recover the original signal, while FBAR and RBAR do.
%[text] This is easier to see in the spectral domain. FASTR has serious persistent artifacts across the spectrum,  FBAR & RBAR perform substantially better, recovering most of the spectrum, except for a band around the tACS frequency.
%%
%[text] %[text:anchor:H_370D044C] ## Impedance Artifacts tACS
%[text] Physiological artifacts such as heartbeats, sweating, or breathing change impedance and interact multiplicatively with the signal. FASTR has a hard time recovering any underlying signals.
%[text] Keeping the neural signals from above, but adding an artifact that rhytmically (`o.zFrequency`) changes the impedance sinusoidally, The maximum change in the impedance is defined (as a fraction) by `o.zAmplitude.`
eeg                           = artSim(eegDefaults);      % Start fresh
eeg.tacsAmplitude             = 1e-3;    % 1 mA -> 1 mV artifact
eeg.tacsFrequency             = 10;      % 10 Hz tACS
eeg.lfpFrequency              = 32;        % Simulated oscillation peak frequency
eeg.lfpAmplitude              = 100e-6;    % Oscillation peak amplitude
eeg.lfpPeakWidth              = 1;         % Oscillation bandwidth.
%[text] Set ar parameters
ar                          = arDefaults;
ar.tacsFrequency            = eeg.tacsFrequency;

%[text] Add physiological arfitacts, first a sinusoidal modulation of the impedance (maybe a reasonable approximation for respiration not so much for a heartbeat):
eeg.zFrequency = 18/60;  % 18 breaths per minute
eeg.zAmplitude = 0.05;  % The artifact changes the impedance by 5%.
[~,axs] = fig('Name','Fig6','paperCols',1.5,'height',9,'nrRows',2,'nrCols',2); %[output:88a7f6bb]
simPlotEEG(eeg,ar,'FASTR',freqRes =0.1,axs=[gobjects(1,2) axs(1)]); %[output:348bef2f] %[output:8705bff3] %[output:5472953a] %[output:88a7f6bb]
%[text] 
simPlotEEG(eeg,ar,'RBAR',freqRes =0.1,axs=[gobjects(1,2) axs(2)]); %[output:87927457] %[output:88a7f6bb]
%[text] Next we simulate a impedance modulation that models the ballistic artifacts expected from a heartbeat. This uses an ECG recording and a simple body resonance model to simulate the ballistic impedance changes. See `zHeartbeat.m` for details.
eeg.zFun = @zHeartbeat ;
simPlotEEG(eeg,ar,'FASTR',freqRes =0.1,axs=[gobjects(1,2) axs(3)]); %[output:9554bf4f] %[output:6179b15b] %[output:9fbc6ea6] %[output:88a7f6bb]
simPlotEEG(eeg,ar,'RBAR',freqRes =0.1,axs=[gobjects(1,2) axs(4)]); %[output:668ca109] %[output:88a7f6bb]
yylinkaxes(axs([2 4])) %[output:88a7f6bb]



%[text] Clearly FASTR (a,c) does not recover the neural signal of either sinusoidal/breathing (a) or pulsed/heartbeat (c) impedance artifacts; the multiplicative interactions between physiological artifacts and the true neural signal results in spurious signals across the entire spectrum.  Noury et al explain why this should happen and why there are two prominent peaks in a).  RBAR gets rid of most artifacts and only has a small forbidden zone near the tACS frequency. FBAR (not shown) has the same kind of issues as FASTR.
%[text] 
%%
%[text] ### Imedance Artifacts tDCS 
%[text] As long as recordings exclude the ramp up and ramp down periods, the DC current generated by tDCS does not introduce neural artifacts on its own.  
%[text] However, impedance artifacts induced by physiological changes such as heartbeats can result in spurious neural signals. 
eeg                           = artSim(eegDefaults);      % Start fresh
eeg.tdcsMean                  = 1e-3;
eeg.lfpFrequency              = 23;        % Simulated oscillation peak frequency
eeg.lfpAmplitude              = 100e-6;    % Oscillation peak amplitude
eeg.lfpPeakWidth              = 1;         % Oscillation bandwidth.
eeg.duration                  = 120;

eeg.zFun  =  @zHeartbeat;
eeg.zAmplitude = 0.05;  % The artifact changes the impedance by 5%.

ar                          = arDefaults;
ar.recordingSamplingRate    = eeg.recordingSamplingRate;
ar.segmentDuration          = 120;      % Define segments in seconds instead of cycles

[~,axs] = fig('Name','Fig7','paperCols',1.5,'height',9,'nrRows',2,'nrCols',2,'span',{[1, 2 1],[2,1,1],[4,1,1]}); %[output:9e116b62]
%[text] Zoom in on the timecourse near a heartbeat to illustrate the effect. To illustrate the heartbeat effect, remove the background activity.
tlim = [0.35 0.65];
eeg.additive                  = 0;
simPlotEEG(eeg,ar,'NOP',freqRes =1,axs=[axs(1) gobjects(1,2)],tlim=tlim,lineWidth=1); %[output:45add7c6] %[output:9e116b62]
%[text] Restore the background activity and show the error spectra.
eeg.additive  =  100e-6;
simPlotEEG(eeg,ar,'NOP',freqRes =1,axs=[gobjects(1,2) axs(2)],tlim=tlim,lineWidth=1); %[output:5456048f] %[output:9e116b62]

simPlotEEG(eeg,ar,'RBAR',freqRes =1,axs=[gobjects(1,2) axs(3)]); %[output:78762513] %[output:9e116b62]
yylinkaxes(axs([2 3])); %[output:9e116b62]

%[text] Overlay the heartbeat for illustration (scaled to the range of the plot).
z = eeg.zFun(eeg);
axes(axs(1)) %[output:9e116b62]

yyaxis right
x =axs(1).Children.XData;
y =axs(1).Children.YData;
cla %[output:9e116b62]

stay  = eeg.tSimulate>tlim(1) & eeg.tSimulate < tlim(2);
h = plot(eeg.tSimulate(stay)-min(eeg.tSimulate(stay)),z(stay),'c-','LineWidth',1); %[output:9e116b62]
%axs(1).Color = 0.95*ones(1,3);
axs(1).YAxis(2).Color = 'c'; %[output:9e116b62]
ylim(1+ eeg.zAmplitude*[-1 1]) %[output:9e116b62]
set(gca,'YTick',1+ eeg.zAmplitude*[-1 1]) %[output:9e116b62]
yyaxis left %[output:9e116b62]
delete(axs(1).Children(2)); %[output:9e116b62]
plot(x,y,'b-') %[output:9e116b62]

legend([axs(1).Children([1 3]);h], 'Neural','Recorded','CBA','Location','none','Position',[0.1283 0.1179 0.1914, 0.1118]) %[output:9e116b62]


